Q: Align &quot;span text&quot; with &quot;h3 text&quot; in a row HTML A: <p>&lt;!DOCTYPE html&gt;</p>
<p>&lt;html&gt;</p>
<p>&lt;body style=&quot;background:#222; color:white; text-align:center;&quot;&gt;</p>
<pre><code>\&lt;h3\&gt;Skor: \&lt;span id=&quot;s&quot;\&gt;0\&lt;/span\&gt; | Waktu: \&lt;span id=&quot;t&quot;\&gt;20\&lt;/span\&gt;\&lt;/h3\&gt;

\&lt;canvas id=&quot;g&quot; style=&quot;background:#333; border:2px solid white;&quot;\&gt;\&lt;/canvas\&gt;

\&lt;script\&gt;

    const c=document.getElementById(&quot;g&quot;), x=c.getContext(&quot;2d&quot;);

    let score=0, time=20, active=true, tx=50, ty=50;

    c.width=300; c.height=300;

    function draw() {

        x.clearRect(0,0,300,300);

        if(active) { x.fillStyle=&quot;red&quot;; x.fillRect(tx,ty,40,40); }

        else { x.fillStyle=&quot;white&quot;; x.fillText(&quot;GAME OVER&quot;,120,150); }

    }

    c.onclick=(e)=\&gt;{

        let r=c.getBoundingClientRect();

        let mx=e.clientX-r.left, my=e.clientY-r.top;

        if(mx\&gt;tx&amp;&amp;mx\&lt;tx+40&amp;&amp;my\&gt;ty&amp;&amp;my\&lt;ty+40&amp;&amp;active){

            score++; document.getElementById(&quot;s&quot;).innerText=score;

            tx=Math.random()\*260; ty=Math.random()\*260; draw();

        }

    };

    setInterval(()=\&gt;{ if(time\&gt;0){time--; document.getElementById(&quot;t&quot;).innerText=time;} else {active=false; draw();} },1000);

    draw();

\&lt;
</code></pre>
<p>/script&gt;</p>
<p>&lt;/body&gt;</p>
<p>&lt;/html&gt;</p>

Q: How to convert vector to set? A: <p>In C++23: <a href="https://stackoverflow.com/a/78208048/5267751">use <code>std::ranges::to</code></a> to avoid repeating the container name twice.</p>
<p>You can either use the pipe syntax or the function call syntax. Add <code>as_rvalue</code> for efficiency if the type is not trivially copyable.</p>
<pre><code>#include &lt;ranges&gt;
#include &lt;vector&gt;
#include &lt;set&gt;
#include &lt;memory&gt;

int main() {
    std::vector&lt;std::unique_ptr&lt;int&gt;&gt; a;
    auto b = std::ranges::to&lt;std::set&gt;(std::views::as_rvalue(a));
    auto c = a | std::views::as_rvalue | std::ranges::to&lt;std::set&gt;();

    std::vector&lt;int&gt; d;
    auto e = std::ranges::to&lt;std::set&gt;(d);
    auto f = d | std::ranges::to&lt;std::set&gt;();
}
</code></pre>
